[
  {
    "title": "光合作用的整體功能",
    "body": "植物利用光能，將二氧化碳和水轉為有機物，並釋放氧氣。",
    "examples": [
      "陽光下的水草常在葉片表面形成氧氣氣泡。"
    ]
  },
  {
    "title": "光反應",
    "body": "光反應在類囊體膜進行；葉綠素吸收光能，分解水並製造 ATP、NADPH，同時釋放氧氣。",
    "examples": [
      "水分子提供光反應所需的電子，分解後產生氧氣。"
    ]
  },
  {
    "title": "碳反應",
    "body": "碳反應在葉綠體基質進行，利用 ATP 和 NADPH 將二氧化碳轉成糖類。",
    "examples": [
      "葉片吸收的二氧化碳會成為製造糖類的碳來源。"
    ]
  }
]
